var n=`0619-ojja-merguez`;var t=`world-0619`;var a=`TN`;var s=`northern-africa`;var r=4;var o=39;var g={en:`Ojja Merguez`,ua:`Ожа з мергезом`};var l={en:`Ojja Merguez is a Tunisia classic prepared with fresh pork sausage, yellow onion, red bell pepper, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Ожа з мергезом, страва кухні країни Туніс зі складниками: сира свиняча ковбаса, жовта цибуля, червоний солодкий перець, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`fresh-pork-sausage`,420,`g`],[`extra-virgin-olive-oil`,35,`ml`],[`yellow-onion`,140,`g`],[`red-bell-pepper`,220,`g`],[`tomato`,330,`g`],[`harissa`,22,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 14 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 14 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:14,i:[[`water`,140,`ml`],[`ground-cumin`,4,`g`]]},{en:`Make four wells in the spicy tomato-and-sausage mixture, crack an egg into each and cover until the whites and yolks are safely set.`,ua:`Зробіть чотири заглиблення в гострому томатному соусі з ковбасками, розбийте по яйцю й накрийте до безпечної готовності білків і жовтків.`,t:[`poaching`],m:10,i:[[`chicken-egg`,4,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`]]}];var d={slug:n,id:t,country:`TN`,region:s,servings:4,minutes:39,title:g,text:l,steps:u};export{a as country,d as default,t as id,o as minutes,s as region,r as servings,n as slug,u as steps,l as text,g as title};